From 881e918f1db8d43541fd034d3d19e484ed33bcdb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:45:56 +0100
Subject: [PATCH] options: turn off animations while the power-saver profile is
 active

Picking Power Save in the Power and Battery widget only changed the CPU
and platform profile, while window and desktop animations kept rendering
frames. KWin now makes animations instant while ppd is in power-saver.

BUG: 467253
---
 src/options.cpp | 44 ++++++++++++++++++++++++++++++++++++++++++++
 src/options.h   |  9 ++++++++-
 2 files changed, 52 insertions(+), 1 deletion(-)

diff --git a/src/options.cpp b/src/options.cpp
index de9552ae0f..26b2429f4e 100644
--- a/src/options.cpp
+++ b/src/options.cpp
@@ -18,8 +18,13 @@

 #include <QProcess>

+#include "dbusproperties_interface.h"
 #include "settings.h"
+#include "utils/dbus.h"
 #include "workspace.h"
+#include <QDBusConnection>
+#include <QDBusConnectionInterface>
+#include <QDBusServiceWatcher>
 #include <QOpenGLContext>
 #include <QQmlEngine>

@@ -95,6 +100,42 @@ Options::Options(QObject *parent)
             workspace()->reconfigure();
         }
     });
+
+    const QString powerProfilesService = QStringLiteral("org.freedesktop.UPower.PowerProfiles");
+    const QString powerProfilesInterface = QStringLiteral("org.freedesktop.UPower.PowerProfiles");
+    m_powerProfilesProperties = std::make_unique<OrgFreedesktopDBusPropertiesInterface>(powerProfilesService, QStringLiteral("/org/freedesktop/UPower/PowerProfiles"), QDBusConnection::systemBus());
+    connect(m_powerProfilesProperties.get(), &OrgFreedesktopDBusPropertiesInterface::PropertiesChanged, this, [this, powerProfilesInterface](const QString &interfaceName, const QVariantMap &properties) {
+        if (interfaceName != powerProfilesInterface) {
+            return;
+        }
+        if (auto it = properties.find(QStringLiteral("ActiveProfile")); it != properties.end()) {
+            setPowerSaving(it->toString() == QLatin1StringView("power-saver"));
+        }
+    });
+
+    const auto fetchActiveProfile = [this, powerProfilesInterface]() {
+        intoFuture<QVariant>(m_powerProfilesProperties->Get(powerProfilesInterface, QStringLiteral("ActiveProfile"))).then(this, [this](const std::expected<QVariant, QDBusError> &result) {
+            if (result.has_value()) {
+                setPowerSaving(result->toString() == QLatin1StringView("power-saver"));
+            }
+        });
+    };
+    m_powerProfilesWatcher = std::make_unique<QDBusServiceWatcher>(powerProfilesService, QDBusConnection::systemBus(), QDBusServiceWatcher::WatchForOwnerChange);
+    connect(m_powerProfilesWatcher.get(), &QDBusServiceWatcher::serviceRegistered, this, fetchActiveProfile);
+    connect(m_powerProfilesWatcher.get(), &QDBusServiceWatcher::serviceUnregistered, this, [this]() {
+        setPowerSaving(false);
+    });
+    if (QDBusConnection::systemBus().interface()->isServiceRegistered(powerProfilesService)) {
+        fetchActiveProfile();
+    }
+}
+
+void Options::setPowerSaving(bool powerSaving)
+{
+    if (m_powerSaving != powerSaving) {
+        m_powerSaving = powerSaving;
+        Q_EMIT animationSpeedChanged();
+    }
 }

 Options::~Options()
@@ -932,6 +973,9 @@ Options::MouseCommand Options::wheelToMouseCommand(MouseWheelCommand com, qreal
 double Options::animationTimeFactor() const
 {
 #ifndef KCMRULES
+    if (m_powerSaving) {
+        return 0;
+    }
     return m_settings->animationDurationFactor();
 #else
     return 0;
diff --git a/src/options.h b/src/options.h
index 30ea9ab6c8..25f8dc3e4f 100644
--- a/src/options.h
+++ b/src/options.h
@@ -20,6 +20,8 @@

 class QQmlEngine;
 class QJSEngine;
+class QDBusServiceWatcher;
+class OrgFreedesktopDBusPropertiesInterface;

 namespace KWin
 {
@@ -647,7 +649,8 @@ public:
     }

     /**
-     * Returns the animation time factor for desktop effects.
+     * Returns the animation time factor for desktop effects. It is 0 while the
+     * power-saver power profile is active.
      */
     double animationTimeFactor() const;

@@ -915,8 +918,12 @@ Q_SIGNALS:
 private:
     void setElectricBorders(int borders);
     void syncFromKcfgc();
+    void setPowerSaving(bool powerSaving);
     std::unique_ptr<Settings> m_settings;
     KConfigWatcher::Ptr m_configWatcher;
+    std::unique_ptr<QDBusServiceWatcher> m_powerProfilesWatcher;
+    std::unique_ptr<OrgFreedesktopDBusPropertiesInterface> m_powerProfilesProperties;
+    bool m_powerSaving = false;

     FocusPolicy m_focusPolicy;
     bool m_nextFocusPrefersMouse;
